mapper.insert:
insert into CHB_PRD_PERIODYIELD(SEQNO, FPROD_ID, PROD_ID, CHANGE_DATE, CHANG_TYPE, PROD_VALUE, ORG_CODE, DEPT_CODE, STATUS, REV_DATE, DATA_SOURCE, UPDATE_USER, UPDATE_TIME, CREATE_USER, CREATE_TIME, REMARK,UNIT_VALUE_TOTAL,CCY,TDY_UNIT_VALUE_SUM) select TEMP.* from (
SELECT #{item.seqno,jdbcType=CHAR} SEQNO, #{item.fprodId,jdbcType=VARCHAR} FPROD_ID, #{item.prodId,jdbcType=VARCHAR} PROD_ID, #{item.changeDate,jdbcType=TIMESTAMP} CHANGE_DATE, #{item.changType,jdbcType=VARCHAR} CHANG_TYPE, #{item.prodValue,jdbcType=DECIMAL} PROD_VALUE, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE, #{item.status,jdbcType=VARCHAR} STATUS, #{item.revDate,jdbcType=TIMESTAMP} REV_DATE, #{item.dataSource,jdbcType=VARCHAR} DATA_SOURCE, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, NOW() UPDATE_TIME, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, NOW() CREATE_TIME, #{item.remark,jdbcType=VARCHAR} REMARK, #{item.unitValueTotal,jdbcType=DECIMAL} UNIT_VALUE_TOTAL, #{item.ccy,jdbcType=VARCHAR} ccy ,#{item.tdyUnitValueSum,jdbcType=DECIMAL} TDY_UNIT_VALUE_SUM FROM DUAL
) TEMP where not exists (select 1 from CHB_PRD_PERIODYIELD CII where CII.PROD_ID = TEMP.PROD_ID AND DATE_FORMAT(CII.CHANGE_DATE,'%Y-%m-%d') = DATE_FORMAT(TEMP.CHANGE_DATE,'%Y-%m-%d') AND CII.CHANG_TYPE = TEMP.CHANG_TYPE);
UPDATE CHB_PRD_PERIODYIELD as A, ( select TEMP.* from (
SELECT #{item.seqno,jdbcType=CHAR} SEQNO, #{item.fprodId,jdbcType=VARCHAR} FPROD_ID, #{item.prodId,jdbcType=VARCHAR} PROD_ID, #{item.changeDate,jdbcType=TIMESTAMP} CHANGE_DATE, #{item.changType,jdbcType=VARCHAR} CHANG_TYPE, #{item.prodValue,jdbcType=DECIMAL} PROD_VALUE, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE, #{item.status,jdbcType=VARCHAR} STATUS, #{item.revDate,jdbcType=TIMESTAMP} REV_DATE, #{item.dataSource,jdbcType=VARCHAR} DATA_SOURCE, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, NOW() UPDATE_TIME, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, NOW() CREATE_TIME, #{item.remark,jdbcType=VARCHAR} REMARK, #{item.unitValueTotal,jdbcType=DECIMAL} UNIT_VALUE_TOTAL, #{item.ccy,jdbcType=VARCHAR} ccy ,#{item.tdyUnitValueSum,jdbcType=DECIMAL} TDY_UNIT_VALUE_SUM FROM DUAL
) TEMP ) AS B set A.PROD_VALUE = B.PROD_VALUE, A.UNIT_VALUE_TOTAL = B.UNIT_VALUE_TOTAL, A.ORG_CODE = B.ORG_CODE, A.DEPT_CODE = B.DEPT_CODE, A.REV_DATE = B.REV_DATE, A.STATUS = B.STATUS, A.REMARK = B.REMARK, A.UPDATE_USER = B.UPDATE_USER, A.UPDATE_TIME = B.UPDATE_TIME, A.CCY = B.CCY ,A.TDY_UNIT_VALUE_SUM = B.TDY_UNIT_VALUE_SUM WHERE A.PROD_ID = B.PROD_ID AND DATE_FORMAT(A.CHANGE_DATE,'%Y-%m-%d') = DATE_FORMAT(B.CHANGE_DATE,'%Y-%m-%d') AND A.CHANG_TYPE = B.CHANG_TYPE;
